class Solution:
    def tallestBillboard(self, rods: list[int]) -> int:
        dp = {0: 0}
        for x in rods:
            cur = dp.copy()
            for diff, short in cur.items():
                dp[diff + x] = max(dp.get(diff + x, 0), short)
                nd = abs(diff - x)
                ns = short + min(diff, x)
                dp[nd] = max(dp.get(nd, 0), ns)
        return dp.get(0, 0)

